 row={'question_id':qid,'revision':q['key']['revision'],'concept_id':q['concept_id'],'category':q['category'],'prompt':text(q['prompt']),'stem_image':q['image'],'options':options,'correct_authored_option_id':q['feedback']['correct_option_id'],'explanation':text(q['feedback']['explanation']),'teaching_and_sources':q['relationship'],'accepted_status':q['acceptance']['eligibility'],'content_review_locator':q['acceptance']['content_review'],'accepted_snapshot_sha256':digest(q),'paired_question_id':dm[qid]['paired_question_id'],'distractor_change':None if qid not in b['distractor_change_ids'] else {'old_codes':p['original_option_codes'],'new_codes':p['proposed_option_codes'],'counted_as_extra_question':False},'independent_review':{'reviewed_on':'2026-10-21','specific_rationale':notes[code],'direction_check':'Meaning: the exact neutral stem has one matching meaning among the four alternatives.' if qid.startswith('sign-meaning-') else 'Recognition: the named meaning identifies one exact illustration; neutral image alternatives disclose appearance rather than code/key.','source_evidence':{k:v for k,v in review['official_source'].items() if k!='content'},'review_method':'Read this exact paired-direction packet, dated primary explanation where available, option meanings and neutral text; visually inspect exact source artwork board. Automated per-ID checks compare every option feedback/source/variant independently. Analytical sheets do not prove device legibility.','source_currency':'Dated primary evidence; not a blanket live legal-source refresh or official endorsement of editorial English.'},'status':'pass' if not fail else 'fail','failures':fail}
 related=[f['id'] for f in read('docs/curriculum/app-migration/verification-evidence/10E1/review-findings.json')['findings'] if any(o['post_answer_code'] in f['asset_codes'] for o in options)]
